SELECT AVG(confidence_score) AS avg_confidence_score
FROM predictions
WHERE model_name = 'LSTM' AND stock_id = 0 AND prediction_date BETWEEN '2023-01-01' AND '2023-05-31';

SELECT AVG(contributions_count) AS avg_contributions_per_contributor
FROM (
    SELECT COUNT(c.contribution_id) AS contributions_count
    FROM contributions c
    GROUP BY c.contributor_id
) AS contributions_summary;

SELECT SUM(metric_value) AS total_sales
FROM partner_performance
WHERE metric_name = 'sales';

SELECT DISTINCT ci.item_name
FROM clothing_items ci
JOIN customer_preferences cp ON ci.item_id = cp.item_id;

SELECT COUNT(DISTINCT al.user_id) AS unique_users_count
FROM access_logs al
JOIN pathfind_results pr ON al.result_id = pr.result_id;

SELECT SUM(results_warnerm) AS total_votes_for_warner
FROM election_results
WHERE election_year = '2022';

SELECT AVG(np.average_latency) AS average_latency
FROM network_performance np
WHERE np.measurement_time BETWEEN '2023-10-01 00:00:00' AND '2023-10-02 23:59:59';

SELECT total_points
FROM team_seasons
WHERE total_points > 10000;

SELECT COUNT(DISTINCT e.event_id) AS total_events, COUNT(DISTINCT ep.driver_id) AS total_unique_drivers
FROM events e
JOIN event_participants ep ON e.event_id = ep.event_id;

SELECT SUM(quantity) AS total_quantity
FROM order_items
WHERE item_id = 0;

SELECT AVG(log_return) AS average_log_return
FROM log_returns
WHERE stock_symbol = '0' AND date BETWEEN '2017-04-01' AND '2017-04-05';
